//! The text of the generated files.

use std::fmt::Write as _;

use anyhow::{Result, bail};
use serde_json::Value;

use super::spec::{Cat, Conv, SHARED_TYPES, Shape, VALUE_ENUMS};
use super::{Ctx, Rec};

pub const COMMAND: &str = "cargo xtask gen-cards";

fn header(what: &str) -> String {
    format!(
        "// @generated by `{COMMAND}` from crates/ti4-content/content/*.json. DO NOT EDIT.\n\
         // {what}\n\
         // To change it: edit the JSON (or the names file in crates/ti4-engine-core/names/) and run\n\
         // `{COMMAND}`; `{COMMAND} --check` fails while this file is stale. See docs/CONTENT_GENERATOR.md.\n\n"
    )
}

/// `u8` when the enum has room to double, else `u16`.
fn repr(count: usize) -> &'static str {
    if count * 2 <= 256 { "u8" } else { "u16" }
}

/// snake_case of a JSON field name (`automationID` -> `automation_id`).
fn snake(field: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = field.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if c.is_ascii_uppercase() {
            let prev_lower =
                i > 0 && (chars[i - 1].is_ascii_lowercase() || chars[i - 1].is_ascii_digit());
            let next_lower = chars.get(i + 1).is_some_and(char::is_ascii_lowercase);
            let prev_upper = i > 0 && chars[i - 1].is_ascii_uppercase();
            if i > 0 && (prev_lower || (prev_upper && next_lower)) {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn rust_type(conv: &Conv) -> String {
    match conv {
        Conv::Flag(_) => "bool".to_owned(),
        Conv::Int { ty, required, .. } => {
            if *required {
                (*ty).to_owned()
            } else {
                format!("Option<{ty}>")
            }
        }
        Conv::Value { enm, shape, .. } => shaped(enm, *shape),
        Conv::Ref { cat, shape, .. } => {
            let ty = super::spec::categories()
                .into_iter()
                .find(|c| c.key == *cat)
                .map_or("?", |c| c.ty);
            shaped(ty, *shape)
        }
        Conv::Custom { ty, .. } => (*ty).to_owned(),
    }
}

fn shaped(ty: &str, shape: Shape) -> String {
    match shape {
        Shape::One => ty.to_owned(),
        Shape::Opt => format!("Option<{ty}>"),
        Shape::List => format!("&'static [{ty}]"),
    }
}

fn doc_lines(out: &mut String, indent: &str, doc: &str) {
    for line in doc.lines() {
        let _ = writeln!(out, "{indent}/// {line}");
    }
}

// ---------------------------------------------------------------- core

pub fn core_mod(cats: &[Cat]) -> String {
    let mut out = header("The core's id enums, value enums and gameplay tables. No strings.");
    out.push_str(
        "//! Generated content tables of the core: one id enum per category (integer order = byte\n\
         //! order of the corpus id), value enums for the closed sets of the corpus, and a typed\n\
         //! gameplay row per record. Strings live in the adapter (`ti4-engine/src/generated/`).\n\n",
    );
    out.push_str("#[rustfmt::skip]\npub mod values;\n");
    for cat in cats {
        let _ = writeln!(out, "#[rustfmt::skip]\npub mod {};", cat.key);
    }
    out.push_str("\npub use values::*;\n");
    for cat in cats {
        let _ = writeln!(
            out,
            "pub use {}::{{{}, {}Data, {}_DATA, {}_NAME_RANK}};",
            cat.key, cat.ty, cat.ty, cat.upper, cat.upper
        );
    }
    out
}

fn enum_block(out: &mut String, ty: &str, doc: &str, variants: &[&str], extra_derive: &str) {
    let count = variants.len();
    doc_lines(out, "", doc);
    let _ = writeln!(
        out,
        "#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash{extra_derive})]\n#[repr({})]\npub enum {ty} {{",
        repr(count)
    );
    for (i, v) in variants.iter().enumerate() {
        let _ = writeln!(out, "    {v} = {i},");
    }
    out.push_str("}\n\n");
    let _ = writeln!(out, "impl {ty} {{");
    let _ = writeln!(
        out,
        "    /// The number of variants.\n    pub const COUNT: usize = {count};"
    );
    let _ = writeln!(
        out,
        "    /// Every variant, in integer order.\n    pub const ALL: [Self; Self::COUNT] = ["
    );
    for v in variants {
        let _ = writeln!(out, "        Self::{v},");
    }
    out.push_str("    ];\n\n");
    out.push_str(
        "    /// The integer value, as an index into the tables.\n    #[must_use]\n    #[inline]\n    pub const fn index(self) -> usize {\n        self as usize\n    }\n\n",
    );
    out.push_str(
        "    /// The variant with this integer value.\n    #[must_use]\n    pub const fn from_index(index: usize) -> Option<Self> {\n        if index < Self::COUNT { Some(Self::ALL[index]) } else { None }\n    }\n",
    );
}

pub fn core_category(cat: &Cat, ctx: &Ctx, rows: &[Vec<String>]) -> String {
    let mut out = header(&format!("Core tables of `{}.json`.", cat.key));
    out.push_str("#[allow(unused_imports)]\nuse super::*;\n\n");
    let recs = ctx.records(cat.key);
    let names = &ctx.names[cat.key];
    let variants: Vec<&str> = recs.iter().map(|r| names[&r.id].as_str()).collect();
    enum_block(&mut out, cat.ty, cat.doc, &variants, "");
    let _ = writeln!(
        out,
        "\n    /// The gameplay row.\n    #[must_use]\n    #[inline]\n    pub fn data(self) -> &'static {ty}Data {{\n        &{up}_DATA[self as usize]\n    }}\n\n    /// The rank of the printed name among all records of the category: 0 is the first in the byte\n    /// order of the name, ties (equal names) by id. A sort by display name or label is a sort by\n    /// this integer ([`{up}_NAME_RANK`]); the core never sees the text.\n    #[must_use]\n    #[inline]\n    pub const fn name_rank(self) -> u16 {{\n        {up}_NAME_RANK[self as usize]\n    }}\n}}\n",
        ty = cat.ty,
        up = cat.upper
    );
    let _ = writeln!(
        out,
        "/// Gameplay data of a [`{ty}`].\n#[derive(Debug, Clone, Copy, PartialEq)]\npub struct {ty}Data {{",
        ty = cat.ty
    );
    for col in &cat.columns {
        doc_lines(&mut out, "    ", col.doc);
        let _ = writeln!(out, "    pub {}: {},", col.name, rust_type(&col.conv));
    }
    out.push_str("}\n\n");
    let _ = writeln!(
        out,
        "/// One row per [`{ty}`], indexed by its integer value.\npub static {up}_DATA: [{ty}Data; {ty}::COUNT] = [",
        ty = cat.ty,
        up = cat.upper
    );
    for (variant, row) in variants.iter().zip(rows) {
        let _ = writeln!(out, "    // {variant}\n    {}Data {{", cat.ty);
        for (col, expr) in cat.columns.iter().zip(row) {
            let _ = writeln!(out, "        {}: {expr},", col.name);
        }
        out.push_str("    },\n");
    }
    out.push_str("];\n");
    name_rank(&mut out, cat, ctx);
    out
}

/// `<UP>_NAME_RANK`: the rank of each record's printed name (`name_field`, else the id) in byte
/// order, ties by id (= by integer value, as the records are in id order).
fn name_rank(out: &mut String, cat: &Cat, ctx: &Ctx) {
    let recs = ctx.records(cat.key);
    let name_of = |r: &Rec| -> String {
        r.fields
            .get(cat.name_field)
            .and_then(Value::as_str)
            .map_or_else(|| r.id.clone(), str::to_owned)
    };
    let mut order: Vec<usize> = (0..recs.len()).collect();
    order.sort_by(|&a, &b| name_of(&recs[a]).cmp(&name_of(&recs[b])).then(a.cmp(&b)));
    let mut rank = vec![0usize; recs.len()];
    for (r, &i) in order.iter().enumerate() {
        rank[i] = r;
    }
    let _ = writeln!(
        out,
        "\n/// The rank of each [`{ty}`]'s printed name (`{field}`) in byte order, ties by id; indexed by its\n/// integer value. A bijection onto `0..COUNT`.\npub static {up}_NAME_RANK: [u16; {ty}::COUNT] = [",
        ty = cat.ty,
        up = cat.upper,
        field = cat.name_field
    );
    for chunk in rank.chunks(16) {
        let line: Vec<String> = chunk.iter().map(ToString::to_string).collect();
        let _ = writeln!(out, "    {},", line.join(", "));
    }
    out.push_str("];\n");
}

pub fn core_values(ctx: &Ctx, faction_tags: bool) -> String {
    let mut out = header("The core's value enums: closed sets of keys collected from the corpus.");
    out.push_str("#[allow(unused_imports)]\nuse super::*;\n");
    out.push_str(SHARED_TYPES);
    out.push('\n');
    for enm in VALUE_ENUMS {
        let variants: Vec<&str> = if let Some(layout) = ctx.layouts.get(enm.name) {
            layout.iter().map(|(v, _)| v.as_str()).collect()
        } else {
            ctx.values
                .get(enm.name)
                .map(|m| m.values().map(String::as_str).collect())
                .unwrap_or_default()
        };
        if variants.is_empty() {
            continue; // used only by categories this run does not generate
        }
        enum_block(&mut out, enm.name, enm.doc, &variants, "");
        out.push_str("}\n\n");
    }
    if faction_tags {
        // A tag names the faction with that id, else every faction whose id starts with it
        // (`keleres` -> `keleresa`, `keleresm`, `keleresx`).
        out.push_str(
            "impl FactionTag {\n    /// The factions this tag stands for: the faction with this id, else every faction whose id\n    /// starts with the tag (`keleres` stands for the three Keleres factions).\n    #[must_use]\n    pub const fn factions(self) -> &'static [Faction] {\n        match self {\n",
        );
        let faction_names = &ctx.names["factions"];
        for (key, variant) in &ctx.values["FactionTag"] {
            let members: Vec<String> = if let Some(name) = faction_names.get(key) {
                vec![format!("Faction::{name}")]
            } else {
                faction_names
                    .iter()
                    .filter(|(id, _)| id.starts_with(key.as_str()))
                    .map(|(_, name)| format!("Faction::{name}"))
                    .collect()
            };
            let _ = writeln!(
                out,
                "            Self::{variant} => &[{}],",
                members.join(", ")
            );
        }
        out.push_str("        }\n    }\n}\n");
    }
    out
}

// ---------------------------------------------------------------- adapter

pub fn adapter_mod(cats: &[Cat], core: &str) -> String {
    let mut out = header("The adapter's id strings and display text.");
    let _ = write!(
        out,
        "//! Generated adapter tables: the corpus id of every core enum variant and the display text\n\
         //! of every record. Not wired into `ti4-engine` yet (no `mod generated;` there): it is\n\
         //! compiled and tested by `crates/ti4-engine-core/tests/adapter.rs` until the core exists.\n\n\
         #[rustfmt::skip]\npub mod values;\n"
    );
    for cat in cats {
        let _ = writeln!(out, "#[rustfmt::skip]\npub mod {};", cat.key);
    }
    let _ = write!(
        out,
        r"
/// The id string of a generated enum. Ids are stored in byte order, so `from_id` is a binary
/// search, and `as_str` an array index.
pub trait IdStr: Copy + Sized + 'static {{
    /// Every id, indexed by the variant's integer value (sorted, byte order).
    const IDS: &'static [&'static str];
    /// The variant with this integer value.
    fn nth(index: usize) -> Option<Self>;
    /// The variant's integer value.
    fn index(self) -> usize;
    /// The corpus id.
    #[must_use]
    fn as_str(self) -> &'static str {{
        Self::IDS[self.index()]
    }}
    /// The variant of a corpus id, `None` for anything else.
    #[must_use]
    fn from_id(id: &str) -> Option<Self> {{
        Self::IDS.binary_search(&id).ok().and_then(Self::nth)
    }}
}}

/// A value enum read from a printed corpus value (a window sentence, an agenda target, ...)
/// through a committed table, `card_fields.json`.
pub trait Printed: Copy + Sized + 'static {{
    /// Every printed value of the corpus with its variant, sorted by printed value.
    const PRINTED: &'static [(&'static str, Self)];
    /// The variant of a printed value (compared trimmed), `None` for a value the table does not list.
    #[must_use]
    fn from_printed(printed: &str) -> Option<Self> {{
        let printed = printed.trim();
        Self::PRINTED
            .binary_search_by(|(p, _)| (*p).cmp(printed))
            .ok()
            .map(|i| Self::PRINTED[i].1)
    }}
}}

/// An id that names a record of the compiled-in corpus or something that only exists at run time:
/// a system or planet created during a game, a seat name, an id of a corpus loaded with
/// `ContentStore::from_dir` that the compiled-in corpus does not have, a composite id such as
/// `support:<faction>` or a generic note's bare alias. The core never sees `Dynamic`: the adapter
/// keeps such ids as strings (or maps them to a per-game table) before calling into the core.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum IdRef<'a, T> {{
    Known(T),
    Dynamic(&'a str),
}}

impl<'a, T: IdStr> IdRef<'a, T> {{
    /// Look an id up; anything the generated enum does not have is `Dynamic`.
    #[must_use]
    pub fn parse(id: &'a str) -> Self {{
        T::from_id(id).map_or(Self::Dynamic(id), Self::Known)
    }}

    /// The id string either way.
    #[must_use]
    pub fn as_str(&self) -> &'a str {{
        match self {{
            Self::Known(known) => known.as_str(),
            Self::Dynamic(id) => id,
        }}
    }}

    /// The generated variant, if it is one.
    #[must_use]
    pub const fn known(&self) -> Option<T> {{
        match self {{
            Self::Known(known) => Some(*known),
            Self::Dynamic(_) => None,
        }}
    }}
}}

#[allow(unused_imports)]
use {core}::*;
"
    );
    out
}

fn ids_impl(out: &mut String, ty: &str, table: &str, ids: &[&str]) {
    let _ = writeln!(
        out,
        "/// The corpus id of each [`{ty}`], indexed by its integer value.\npub static {table}: [&str; {ty}::COUNT] = ["
    );
    for id in ids {
        let _ = writeln!(out, "    {id:?},");
    }
    out.push_str("];\n\n");
    let _ = writeln!(
        out,
        "impl IdStr for {ty} {{\n    const IDS: &'static [&'static str] = &{table};\n    #[inline]\n    fn nth(index: usize) -> Option<Self> {{\n        Self::from_index(index)\n    }}\n    #[inline]\n    fn index(self) -> usize {{\n        self as usize\n    }}\n}}\n"
    );
}

/// The Rust type of a display field, from the values it takes across a category.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DisplayType {
    Str,
    OptStr,
    StrList,
    Bool,
}

fn display_type(recs: &[Rec], field: &str, key: &str) -> Result<DisplayType> {
    let (mut strings, mut absent, mut lists, mut bools) = (0, 0, 0, 0);
    for rec in recs {
        match rec.fields.get(field) {
            None | Some(Value::Null) => absent += 1,
            Some(Value::String(_)) => strings += 1,
            Some(Value::Bool(_)) => bools += 1,
            Some(Value::Array(items)) if items.iter().all(Value::is_string) => lists += 1,
            Some(other) => bail!("{key}.{field}: unsupported display value {other}"),
        }
    }
    Ok(match (strings, lists, bools) {
        (_, 0, 0) if absent == 0 => DisplayType::Str,
        (_, 0, 0) => DisplayType::OptStr,
        (0, _, 0) => DisplayType::StrList,
        (0, 0, _) => DisplayType::Bool,
        _ => bail!("{key}.{field}: mixed display value types"),
    })
}

pub fn adapter_category(cat: &Cat, ctx: &Ctx, core: &str) -> Result<String> {
    let mut out = header(&format!(
        "Adapter tables of `{}.json`: ids and display text.",
        cat.key
    ));
    let _ = writeln!(out, "use {core}::{};\n\nuse super::IdStr;\n", cat.ty);
    let recs = ctx.records(cat.key);
    let ids: Vec<&str> = recs.iter().map(|r| r.id.as_str()).collect();
    ids_impl(&mut out, cat.ty, &format!("{}_IDS", cat.upper), &ids);

    let mut fields = Vec::new();
    for field in cat.display {
        fields.push((*field, snake(field), display_type(recs, field, cat.key)?));
    }
    let _ = writeln!(
        out,
        "/// Display text of a [`{ty}`] (fields of `{key}.json`, verbatim).\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct {ty}Text {{",
        ty = cat.ty,
        key = cat.key
    );
    for (field, name, ty) in &fields {
        let rust = match ty {
            DisplayType::Str => "&'static str",
            DisplayType::OptStr => "Option<&'static str>",
            DisplayType::StrList => "&'static [&'static str]",
            DisplayType::Bool => "bool",
        };
        let _ = writeln!(out, "    /// `{field}`\n    pub {name}: {rust},");
    }
    out.push_str("}\n\n");
    let _ = writeln!(
        out,
        "/// One row per [`{ty}`], indexed by its integer value.\npub static {up}_TEXT: [{ty}Text; {ty}::COUNT] = [",
        ty = cat.ty,
        up = cat.upper
    );
    for rec in recs {
        let _ = writeln!(out, "    {}Text {{", cat.ty);
        for (field, name, ty) in &fields {
            let value = rec.fields.get(*field);
            let expr = match (ty, value) {
                (DisplayType::Str, Some(Value::String(s))) => format!("{s:?}"),
                (DisplayType::OptStr, Some(Value::String(s))) => format!("Some({s:?})"),
                (DisplayType::OptStr, _) => "None".to_owned(),
                (DisplayType::StrList, Some(Value::Array(items))) => format!(
                    "&[{}]",
                    items
                        .iter()
                        .filter_map(Value::as_str)
                        .map(|s| format!("{s:?}"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                (DisplayType::StrList, _) => "&[]".to_owned(),
                (DisplayType::Bool, Some(Value::Bool(b))) => b.to_string(),
                (DisplayType::Bool, _) => "false".to_owned(),
                (DisplayType::Str, _) => bail!("{}.{field} missing on {}", cat.key, rec.id),
            };
            let _ = writeln!(out, "        {name}: {expr},");
        }
        out.push_str("    },\n");
    }
    out.push_str("];\n\n");
    let _ = writeln!(
        out,
        "/// The display text of a [`{ty}`].\n#[must_use]\n#[inline]\npub fn text(id: {ty}) -> &'static {ty}Text {{\n    &{up}_TEXT[id as usize]\n}}",
        ty = cat.ty,
        up = cat.upper
    );
    Ok(out)
}

pub fn adapter_values(ctx: &Ctx, core: &str) -> String {
    let mut out = header("The adapter's strings of the value enums (the corpus keys).");
    let _ = writeln!(
        out,
        "#[allow(unused_imports)]\nuse {core}::*;\n\nuse super::{{IdStr, Printed}};\n"
    );
    for enm in VALUE_ENUMS {
        let table = format!("{}_KEYS", super::emit::snake(enm.name).to_ascii_uppercase());
        if let Some(layout) = ctx.layouts.get(enm.name) {
            // Table-driven: the key of a variant is its printed value when there is one per
            // variant, else its name; the printed values of the corpus map to variants through
            // `*_PRINTED` (sorted by printed value, so `from_printed` is a binary search).
            let keys: Vec<&str> = layout.iter().map(|(_, k)| k.as_str()).collect();
            ids_impl(&mut out, enm.name, &table, &keys);
            let rows = &ctx.values[enm.name];
            let printed_table = format!(
                "{}_PRINTED",
                super::emit::snake(enm.name).to_ascii_uppercase()
            );
            let _ = writeln!(
                out,
                "/// Every printed value of the corpus with its [`{enm}`], sorted by printed value.\npub static {printed_table}: [(&str, {enm}); {n}] = [",
                enm = enm.name,
                n = rows.len()
            );
            for (printed, variant) in rows {
                let _ = writeln!(out, "    ({printed:?}, {}::{variant}),", enm.name);
            }
            out.push_str("];\n\n");
            let _ = writeln!(
                out,
                "impl Printed for {enm} {{\n    const PRINTED: &'static [(&'static str, Self)] = &{printed_table};\n}}\n",
                enm = enm.name
            );
            continue;
        }
        let keys: Vec<&str> = ctx.values[enm.name].keys().map(String::as_str).collect();
        if keys.is_empty() {
            continue;
        }
        ids_impl(&mut out, enm.name, &table, &keys);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::snake;

    #[test]
    fn json_fields_become_snake_case() {
        assert_eq!(snake("automationID"), "automation_id");
        assert_eq!(snake("windowEffect"), "window_effect");
        assert_eq!(snake("text1"), "text1");
        assert_eq!(snake("isFakeAttachment"), "is_fake_attachment");
        assert_eq!(snake("FactionTag"), "faction_tag");
    }
}
